use super::*;
struct OriginalSchemaWallet{grant:RetainedCloneGrant,progress:RetainedCloneProgress}
impl ReceivingWallet for OriginalSchemaWallet{
 fn admit_frontier(&self,demand:RetainedCloneGrant)->Result<()>{let remaining=RetainedCloneGrant{maximum_items:self.grant.maximum_items-self.progress.copied_items,maximum_copy_bytes:self.grant.maximum_copy_bytes-self.progress.copied_bytes,..self.grant};if demand.maximum_items>remaining.maximum_items{return Err(error(ValueRefusalKind::WorkLimit,"original schema work grant refused"))}if demand.maximum_copy_bytes>remaining.maximum_copy_bytes||demand.maximum_capacity_bytes>remaining.maximum_capacity_bytes||demand.maximum_release_bytes>remaining.maximum_release_bytes||demand.maximum_depth>remaining.maximum_depth{return Err(error(ValueRefusalKind::OwnershipLimit,"original schema physical grant refused"))}Ok(())}
 fn record_progress(&mut self,progress:RetainedCloneProgress)->Result<()>{self.progress=self.progress.checked_add(progress)?;Ok(())}
 fn allocate_vec_into<T>(&mut self,_:&mut NativeDecodeControl<'_>,_:usize,_:&mut Vec<T>,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no allocating operation"))}
 fn allocate_encode_vec_into<T>(&mut self,_:&mut NativeEncodeControl<'_>,_:usize,_:&mut Vec<T>,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no allocating operation"))}
 fn copy_text_into(&mut self,_:&mut NativeDecodeControl<'_>,_:&str,_:&mut String,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no text producer"))}
 fn copy_encode_text_into(&mut self,_:&mut NativeEncodeControl<'_>,_:&str,_:&mut String,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no text producer"))}
}
#[test]
fn sqlite_snapshot_receiving_borrowed_schema_uses_original_work_without_owned_tokens(){
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(fixture["grant"].clone()).unwrap();let authored=fixture["authoredSql"].as_str().unwrap();
 let script="import{Database}from'bun:sqlite';const f=JSON.parse(await Bun.stdin.text());const reference=new Database(':memory:');reference.run(f.authoredSql);const expected=reference.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all();const results=f.cases.map(c=>{const db=new Database(':memory:');try{db.run(c.sql);const authored=new Database(':memory:');try{authored.run(c.authoredSql??f.authoredSql);const expected=authored.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all();return JSON.stringify(db.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all())===JSON.stringify(expected)}finally{authored.close()}}catch{return false}finally{db.close()}});reference.run('INSERT INTO retained_value VALUES(?,?)',f.extentRow);const extent=reference.query('SELECT count(*) AS rows,sum(8+length(CAST(value AS BLOB))) AS bytes FROM retained_value').get();const extents=f.extentCases.map(c=>extent.rows<=c.maximumRows&&2<=c.maximumColumns&&extent.bytes<=c.maximumValueBytes);reference.close();await Bun.write(Bun.stdout,JSON.stringify({schema:results,extents}));";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(fixture.to_string().as_bytes()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let expected:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();
 for(case,independent)in fixture["cases"].as_array().unwrap().iter().zip(expected["schema"].as_array().unwrap()){let sql=case["sql"].as_str().unwrap();let declaration=case["authoredSql"].as_str().unwrap_or(authored);let name=case["table"].as_str().unwrap_or(fixture["table"].as_str().unwrap());let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:name.into(),sql:sql.into(),rows:Vec::new()}]};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,Default::default());let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant,progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(result,born,released)=crate::test_allocation::observe_backing(||validate_schema_sql(&database,declaration,&mut port));assert_eq!(result.is_ok(),case["accepted"].as_bool().unwrap(),"{}",case["id"]);assert_eq!(independent.as_bool().unwrap(),case["oracleAccepted"].as_bool().unwrap());assert_eq!((born,released),(0,0));assert!(body.progress.copied_items>0);assert_eq!(native.owned_bytes(),0);}
 for(case,independent)in fixture["extentCases"].as_array().unwrap().iter().zip(expected["extents"].as_array().unwrap()){
  let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:fixture["table"].as_str().unwrap().into(),sql:authored.into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(fixture["extentRow"][0].as_i64().unwrap()),SqliteValue::Text(fixture["extentRow"][1].as_str().unwrap().into())]}]}]};let limits=super::super::super::SqliteDatabaseLimits{max_rows:case["maximumRows"].as_u64().unwrap()as usize,max_columns:case["maximumColumns"].as_u64().unwrap()as usize,max_value_bytes:case["maximumValueBytes"].as_u64().unwrap()as usize,..Default::default()};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,limits);let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant,progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(result,born,released)=crate::test_allocation::observe_backing(||check_database(&database,&mut port));assert_eq!(result.is_ok(),case["accepted"].as_bool().unwrap(),"{}",case["id"]);assert_eq!(result.is_ok(),independent.as_bool().unwrap());assert_eq!((born,released),(0,0));assert!(body.progress.copied_items>0);assert_eq!(native.owned_bytes(),0);
 }
 let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:fixture["table"].as_str().unwrap().into(),sql:authored.into(),rows:Vec::new()}]};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,Default::default());let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant:RetainedCloneGrant{maximum_items:0,..grant},progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(error,born,released)=crate::test_allocation::observe_backing(||validate_schema_sql(&database,authored,&mut port).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((born,released),(0,0));assert_eq!(body.progress,Default::default());
 eprintln!("[DEBUG] Original SQLite borrowed authored schema matches {} schema and {} extent independent Bun SQLite outcomes with literal semicolons, exact quoted default case, escaped/Unicode/bracket identifiers, SQL comments, invalid keyword/quote refusal, zero actual token/index allocation, original paid work and unchanged zero-work authority",fixture["cases"].as_array().unwrap().len(),fixture["extentCases"].as_array().unwrap().len());
}
